'use client';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { useEffect, useRef, useState } from 'react';
import { navigation } from '@/lib/content';
import { OakMark } from './brand';
export function Navigation() {
  const path = usePathname();
  const [open, setOpen] = useState(false);
  const toggle = useRef<HTMLButtonElement>(null);
  useEffect(() => { if (!open) return; const handle = (e: KeyboardEvent) => { if (e.key === 'Escape') { setOpen(false); toggle.current?.focus(); } }; document.addEventListener('keydown', handle); return () => document.removeEventListener('keydown', handle); }, [open]);
  return <header className="site-header"><Link href="/" className="brand" aria-label="Oak Field Research home" onClick={() => setOpen(false)}><OakMark /><span>OAK FIELD<span className="brand-sub">RESEARCH</span></span></Link><button ref={toggle} className="menu-toggle" aria-expanded={open} aria-controls="main-navigation" onClick={() => setOpen(!open)}>{open ? 'Close' : 'Menu'}<span aria-hidden="true">{open ? '−' : '+'}</span></button><nav id="main-navigation" aria-label="Main navigation" className={open ? 'main-nav is-open' : 'main-nav'}>{navigation.map(item => <Link href={item.href} key={item.href} onClick={() => setOpen(false)} aria-current={path === item.href ? 'page' : undefined}>{item.label}{item.href === '/enquiries' && <span aria-hidden="true">↗</span>}</Link>)}</nav></header>;
}
